<?php $this->layout('layouts/studio'); ?>
<section class="studio-page-header"><div><small>APARÊNCIA</small><h2>Banners e destaques</h2><p>Gerencie as imagens e chamadas principais do site.</p></div><a class="studio-btn primary" href="<?= url('/operation/slide') ?>"><ion-icon name="add-outline"></ion-icon>Novo destaque</a></section>
<section class="studio-panel studio-content-list"><header><div><h2>Lista de destaques</h2><small><?= count($slides) ?> registro(s)</small></div></header><div class="studio-table-wrap"><table class="studio-table studio-content-table"><thead><tr><th>Destaque</th><th>Alinhamento</th><th>Status</th><th>Publicação</th><th class="studio-table-action">Ações</th></tr></thead><tbody><?php if (!$slides): ?><tr><td colspan="5"><div class="studio-empty">Nenhum destaque cadastrado.</div></td></tr><?php endif; ?><?php foreach ($slides as $item): ?><tr><td><div class="studio-content-item"><span class="studio-content-thumb wide" style="<?= $item->cover?'background-image:url('.image($item->cover,300).')':'' ?>"><ion-icon name="image-outline"></ion-icon></span><span><strong><?= htmlspecialchars($item->title) ?></strong><small><?= htmlspecialchars('/'.$item->uri) ?></small></span></div></td><td><?= ['left'=>'Esquerda','center'=>'Centro','right'=>'Direita'][$item->position]??htmlspecialchars($item->position) ?></td><td><span class="status <?= $item->status ?>"><?= $item->status==='post'?'Publicado':'Rascunho' ?></span></td><td><?= date_fmt($item->post_at,'d/m/Y H:i') ?></td><td class="studio-table-action"><div class="studio-row-actions"><a href="<?= url('/operation/slide/'.$item->id) ?>" title="Editar"><ion-icon name="create-outline"></ion-icon></a></div></td></tr><?php endforeach; ?></tbody></table></div></section>
